        if (!k) return;
        const targetX = st > 6.8 ? 3.2 : 20 - st * 1.05;
        k.model.position.x += (targetX - k.model.position.x) * Math.min(1, dt * 1.8);
        k.yaw = -Math.PI / 2;
        k.model.rotation.y = k.yaw;
        if (st > 6.8) k.mode = 'chase';
        else if (st > 2) k.mode = 'walk';
