class Game {
  constructor(canvas) {
    this.canvas = canvas;
    this.state = 'title';
    this.time = 0;
    this.inputActive = false;
    this.noteOpen = false;
    this.paused = false;
    this.blood = 0;
    this.shakeLevel = 0;
    this.shakeTimer = 0;
    this.noiseLevel = 0;
    this.proximity = 0;
    this.downEntity = null;
    this.afterCutscene = null;
    this.touch = matchMedia('(pointer: coarse)').matches;
    this.camYaw = Math.PI;
    this.pitch = 0;
    this.joystick = { x: 0, y: 0 };
    this.sprintHeld = false;
    this.crouchHeld = false;
    this.torchHeld = false;
    this.rescueHold = 0;
    this.rescueTarget = null;
    this._uiTimer = 0;
    this._heartTimer = 0;
    this._objectiveTimer = 0;
    this._titleAngle = 0;
    this.keysPressed = {};
    this.pendingSwitch = 0;
    this.stats = { notes: 0, started: 0, escaped: 0, finished: false };
    // adaptive resolution: keep the graphics, spend fewer pixels on weak GPUs
    this.baseDpr = 1;
    this.renderDpr = 1;
    this._perfAcc = 0;
    this._perfN = 0;
  }

  init() {
    UI.init();
    this.renderer = new THREE.WebGLRenderer({ canvas: this.canvas, antialias: true, powerPreference: 'high-performance' });
    this.baseDpr = this.renderDpr = Math.min(window.devicePixelRatio || 1, 1.5);
    this.renderer.setPixelRatio(this.baseDpr);
