    // 4 — impact / axe goes flying
    {
      dur: 4.8, fov: 48, fovTo: 34, handheld: 0.02, shake: 0.04,
      from: v(50.8, 1.15, 1.8), to: v(49.2, 1.55, 1.2),
      lookFrom: v(42.8, 1.5, 0), lookTo: v(40.8, 0.65, 0.4),
