    ['seniors', -16.8, -22.3], ['corridor', -47, 2.2], ['corridor', 44, -2.2]
  ];
  const lockedSet = new Set(this.lockedRooms.map(r => r.id));
  const valid = spots.filter(([id]) => id === 'corridor' || !lockedSet.has(id));
