Now replace shots 5 & 6 in introShots with new skip shot. The old text starts at `// 5 — bell / lockdown` and goes until the closing `];\n}` of introShots. We need to replace from `    // 5 — bell / lockdown` through the end of shot 6 and closing. Let's use a targeted edit with the full old block. It's long, but we can use Python to locate. Easier: use Python to find the substring from "    // 5 — bell / lockdown" to "\n  ];\n}" and replace. We'll craft the new shot.

New skip-class shot:

```
    // 5 — the plan
    {
      dur: 6.8, fov: 46, fovTo: 55, handheld: 0.014,
      from: v(-6.35, 1.72, 8.2), to: v(-7.1, 1.62, 6.1),
      lookFrom: v(-4.8, 1.25, 10.4), lookTo: v(-8.0, 1.35, 3.6),
      onStart: (c) => {
        teacher.yaw = 0; teacher.model.rotation.y = 0;
        jake.seated = false;
        jake.quizStyle = null;
        jake.model.position.set(-4.4, 0, 10.9);
        jake.model.rotation.y = Math.PI;
        c.game.audio?.ui();
        UI.cineCard('12:01 PM — FOURTH PERIOD', 'THE PLAN', 'left');
      },
      lines: [
        { at: 0.4, who: 'JAKE', text: 'Psst. Bathroom. Now. Before she assigns us a personality.', actor: jake, dur: 3.0 },
        { at: 3.6, who: 'MS. VELLA', text: 'I can hear whispering. Whispering is a gateway drug.', actor: teacher, dur: 2.6 },
        { at: 5.9, who: 'JAKE', text: 'Go. Go. Go.', actor: jake, dur: 1.2 }
      ],
      onUpdate: (c, st, dt) => {
        // Jake slips down the aisle and out the door; the player follows.
        if (st > 5.7) {
          const p = jake.model.position;
          p.x += (-8.0 - p.x) * Math.min(1, dt * 2.4);
          p.z += (-2.9 - p.z) * Math.min(1, dt * 2.2);
          jake.mode = 'walk';
        } else {
          jake.mode = 'idle';
        }
      },
      cards: [{ at: 0.2, kicker: 'CHAPTER ZERO', title: 'SKIP CLASS', align: 'center', dur: 2.6 }],
      onEnd: (c) => { UI.cineHideCard(); jake.model.visible = false; }
    }
  ];
}
