Design:
```
export function lockdownShots(cine) {
  const game=cine.game;
  const world=game.world;
  world.setLighting('day');
  world.setBodiesVisible(false);

  const jake = cine.person({...}, -3.4,-6.4, Math.PI/2); // facing what? Put near sinks
  jake.model.rotation.y = Math.PI/2? 
  // light in toilet
  cine.light(0xdff3ff, 2.2, 10, -3, 2.8, -8);
  let lockdownOn=false;

  return [
    // 0 — the toilets, one second of peace
    {
      dur: 6.2, fov: 58, fovTo: 46, handheld: 0.02,
      from: v(-2.4, 1.7, -5.2), to: v(-2.2, 1.55, -8.4),
      lookFrom: v(-2.0, 1.4, -3.0), lookTo: v(-2.2, 1.3, -3.0),
      onStart: (c) => { UI.cineCard('12:04 PM — BOYS’ TOILETS','MADE IT','left'); c.game.audio?.setTension(0.15); },
      lines: [
        { at:0.4, who:'JAKE', text:'We made it. Nobody saw us. We are ghosts.', actor:jake, dur:2.6},
        { at:3.2, who:'JAKE', text:'I am never leaving this room. This is my kingdom now.', actor:jake, dur:2.6}
      ],
      onUpdate: (c, st) => {
        if (!lockdownOn && st > 3.2) {
          lockdownOn = true;
          world.setLighting('lockdown');
          bellLine(c.game.audio);
          intercom(c.game.audio);
          c.game.audio?.alarmStart();
          c.game.audio?.stinger();
          UI.cineFlash();
          jake.reaction = 1;
        }
