 const nodes=w.navNodes.filter(n=>n.x>-52&&n.x<52&&n.z<2&&n.z>-42);
 const a=this.game.avatar;
 const downed=[this.game.player,...this.game.bots].filter(e=>e.downed && !e.dead);
 const now=this.game.time;
 let best=null, bestScore=-1e9;
 for (const n of nodes) {
   const key = Math.round(n.x/5)+','+Math.round(n.z/5);
   const last = this._visited.get(key) ?? -999;
   let score = Math.min(1,(now-last)/50)*3.5 + Math.random()*1.4;
   const md = Math.hypot(n.x-this.pos.x,n.z-this.pos.z);
   if (md < 7) score -= 3;
   if (md > 42) score -= 1.5;
   if (a && !a.dead && !a.escaped) {
      const ad=Math.hypot(n.x-a.pos.x,n.z-a.pos.z);
      if (ad > 7 && ad < 24) score += 0.9;
      else if (ad <= 7) score -= 0.7;
   }
   for (const d of downed) {
      const dd=Math.hypot(n.x-d.pos.x,n.z-d.pos.z);
      if (dd < 12) score -= 5;
   }
   if (score>bestScore) {bestScore=score;best=n;}
 }
 if (!best) best={x:this.pos.x+10,z:0};
 this._visited.set(Math.round(best.x/5)+','+Math.round(best.z/5), now);
 return {x:best.x + (Math.random()-0.5)*2, z:best.z + (Math.random()-0.5)*1.2};
}
