  await page.waitForFunction(() => window.__game.cinematic.active && window.__game.cinematic.name === 'lockdown', null, { timeout: 20000 });
  const lock = await page.evaluate(()=>window.__game.cinematic.shots.length);
  console.log('LOCKDOWN SHOTS', lock, 'phase', await page.evaluate(()=>window.__game.phase));
  await sleep(900);
  await page.screenshot({ path:'/tmp/opencode/story-lockdown.jpg', type:'jpeg', quality: 84 });
  await page.evaluate(() => window.__game.cinematic.finish());
  await page.waitForFunction(() => window.__game.phase === 'play' && window.__game.state === 'play', null, { timeout: 30000 });
  await page.waitForTimeout(1200);
  console.log('PLAY', JSON.stringify(await page.evaluate(()=>{const g=window.__game;return {
    p:[+g.player.pos.x.toFixed(1),+g.player.pos.z.toFixed(1)], killerActive:g.killer.active,
    bots:g.bots.map(b=>({d:b.dormant,e:b.escaped,p:[+b.pos.x.toFixed(1),+b.pos.z.toFixed(1)]})),
    jake:g.jake.active, principal:g.principal.active, obj:document.querySelector('#objective-text').textContent
  };})));
  await page.screenshot({ path:'/tmp/opencode/story-chapter1.jpg', type:'jpeg', quality: 84 });

  // force everyone out so the forgotten-Jake beat plays
  await page.evaluate(() => {
    const g=window.__game;
    g.player.escaped = true;
    for (const b of g.bots) { b.escaped = true; b.model.visible = false; }
    g.finishRun();
  });
  await page.waitForFunction(() => window.__game.cinematic.active && window.__game.cinematic.name === 'forgot', null, { timeout: 30000 });
  console.log('FORGOT SHOTS', await page.evaluate(()=>window.__game.cinematic.shots.length));
  await sleep(1400);
  await page.screenshot({ path:'/tmp/opencode/story-forgot.jpg', type:'jpeg', quality: 84 });
  await page.evaluate(() => window.__game.cinematic.finish());
  await page.waitForFunction(() => window.__game.cinematic.active && window.__game.cinematic.name === 'jake', null, { timeout: 30000 });
  console.log('JAKE SHOTS', await page.evaluate(()=>window.__game.cinematic.shots.length));
  await sleep(1100);
  await page.screenshot({ path:'/tmp/opencode/story-jake.jpg', type:'jpeg', quality: 84 });
  await page.evaluate(() => window.__game.cinematic.finish());
  await page.waitForFunction(() => window.__game.cinematic.active && window.__game.cinematic.name === 'police', null, { timeout: 30000 });
  console.log('POLICE SHOTS', await page.evaluate(()=>window.__game.cinematic.shots.length));
  await page.evaluate(() => window.__game.cinematic.finish());
  await page.waitForFunction(() => window.__game.state === 'win', null, { timeout: 30000 });
  const win = await page.evaluate(()=>({
    visible: !document.querySelector('#win-screen').classList.contains('hidden'),
    grade: document.querySelector('#win-grade').textContent,
    stats: document.querySelector('#win-stats').innerText,
    line: document.querySelector('#win-line').textContent
  }));
  console.log('WIN', JSON.stringify(win));
  await sleep(900);
  await page.screenshot({ path:'/tmp/opencode/story-win.jpg', type:'jpeg', quality: 84 });
  console.log('ERRS', errs.length, errs.slice(0,5));
  await browser.close();
})();
