cd /tmp/opencode && cat > story3.cjs <<'EOF'
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const sleep = ms => new Promise(r=>setTimeout(r,ms));
(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader','--ignore-gpu-blocklist'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  page.setDefaultTimeout(120000);
  const errs=[]; page.on('pageerror', e=>{errs.push(e.message); console.log('ERR',e.message);});
  await page.goto('http://localhost:8123/', { waitUntil: 'load' });
  await page.waitForTimeout(2400);
  await page.click('#btn-play');
  await page.waitForFunction(() => window.__game.cinematic.active === true, null, { timeout: 30000 });
  await page.evaluate(() => window.__game.cinematic.finish());
  await page.waitForFunction(() => window.__game.phase === 'skip' && window.__game.state === 'play', null, { timeout: 30000 });
  await page.waitForTimeout(700);
  await page.screenshot({ path:'/tmp/opencode/story3-skip.jpg', type:'jpeg', quality: 84 });

  await page.evaluate(() => { const g=window.__game; g.player.pos.set(-4.2,0,-4.6); g.principal.detect=0; });
  await page.waitForFunction(() => window.__game.cinematic.active && window.__game.cinematic.name === 'lockdown', null, { timeout: 20000 });
  await sleep(1000);
  await page.screenshot({ path:'/tmp/opencode/story3-lockdown.jpg', type:'jpeg', quality: 84 });
  await page.evaluate(() => window.__game.cinematic.finish());
  await page.waitForFunction(() => window.__game.phase === 'play' && window.__game.state === 'play', null, { timeout: 30000 });
  await page.waitForTimeout(1800);
  await page.screenshot({ path:'/tmp/opencode/story3-chapter1.jpg', type:'jpeg', quality: 84 });

  // patrol target variety + downed-student veto
  const patrol = await page.evaluate(() => {
    const g = window.__game;
    const fake = g.bots[0];
    fake.downed = true; fake.dead = false;
    fake.pos.set(-8.5, 0, -14);
    const out = [];
    for (let i = 0; i < 14; i++) {
      g.time += 11;
      const t = g.killer.pickPatrolTarget();
      out.push([+t.x.toFixed(1), +t.z.toFixed(1)]);
    }
    fake.downed = false;
    const near = out.filter(([x,z]) => Math.hypot(x+8.5, z+14) < 12.5);
    const uniq = new Set(out.map(p=>p.join(','))).size;
    return { out, near, uniq };
  });
  console.log('PATROL', JSON.stringify(patrol));

  // movement / no stuck at closed door
  await page.evaluate(() => {
    const g = window.__game;
    g.player.pos.set(-2.0, 0, -4.4);
    g.killer.spawn(34, 0);
    g.killer.state = 'patrol';
    g.killer.patrolTimer = 0;
  });
  const track = [];
  for (let i = 0; i < 5; i++) {
    await sleep(1600);
    track.push(await page.evaluate(() => {
      const g = window.__game;
      return [+g.killer.pos.x.toFixed(1), +g.killer.pos.z.toFixed(1), g.killer.state];
    }));
  }
  console.log('TRACK', JSON.stringify(track));

  // forgot-Jake lighting
  await page.evaluate(() => {
    const g=window.__game;
    g.player.escaped = true;
    for (const b of g.bots) { b.escaped = true; b.model.visible = false; }
    g.finishRun();
  });
  await page.waitForFunction(() => window.__game.cinematic.active && window.__game.cinematic.name === 'forgot', null, { timeout: 30000 });
  await sleep(1500);
  await page.screenshot({ path:'/tmp/opencode/story3-forgot.jpg', type:'jpeg', quality: 84 });
  console.log('ERRS', errs.length, errs.slice(0,5));
  await browser.close();
})();
