import * as THREE from 'three';
import { World } from './world.js';
import { audio } from './audio.js';
import { UI, sleep } from './ui.js';
import { Bot, BOT_DEFS, DOWN_TIME, JakeNPC } from './bots.js';
import { Killer } from './killer.js';
import { Principal } from './principal.js';
import { makePerson, animatePerson } from './props.js';
import { TownTitle } from './title.js';
import { VisibilityCuller } from './culling.js';
import {
  Cinematic, introShots, lockdownShots, forgotJakeShots, jumpscareShots,
  jakeRevealShots, policeShots
} from './cinematics.js';
    if (toiletDoor) {
      toiletDoor.locked = false;
      toiletDoor.setOpen(true, false);
    }

    // Start just inside Room 101. The door is closed, so Okafor cannot see
    // the player until they choose to open it and step into the hall.
    this.player.pos.set(-8.0, 0, 4.15);
    this.player.yaw = 0;
    this.camYaw = 0;
    this.pitch = -0.02;
    this.player.hp = 100;
    this.player.stamina = 100;
    this.player.battery = 100;
    this.player.crowbar = false;
    this.player.torchOn = false;
    this.player.downed = false;
    this.player.hidden = false;
    this.avatar = this.player;
    this.controlledBot = null;
    this.downEntity = null;

    this.jake.spawn(-8.6, 4.55, 0);
    this.bots.forEach(b => {
      b.dormant = true;
      b.model.visible = false;
      b.danger.visible = false;
      b.state = 'follow';
    });

    UI.hideScreens();
    UI.showHud(true);
    UI.setTouch(this.touch);
    UI.fade(false, 900);
    UI.letterbox(false);
    UI.showCine(false);
    UI.chapter('CHAPTER ZERO', 'SKIP CLASS', 3400);
    UI.toast('Reach the toilets with Jake. Do not let Okafor see you.');
    audio.startAmbience();
    audio.alarmStop();
    audio.chaseStop();

Comment says door is closed but we open the toilet door, not classroom. The classroom door auto-opens. Fine. Update comment and spawns.

Player spawn at (-8.0,4.15) facing north; Jake at (-8.6,2.3) outside.

Class bots: use their original constructor spots? Those are (-12.8,5.3), (-3.4,5.3), (-12.8,9.3). -3.4 is east of the door, fine, but that's within Room 101 (x -14..-2). At z5.3 near Jake's desk. Better use intro desk spots: Maya(-11.6,8.5), Devon(-11.6,6.1), Priya(-9.0,10.9). Use those to be consistent with intro. Add teacher.

Create teacher lazily:
```
if (!this.classTeacher) {
  this.classTeacher = makePerson({...});
  this.scene.add(this.classTeacher);
}
this.classTeacher.position.set(-10.7,0,15.0);
this.classTeacher.rotation.y = Math.PI;
this.classTeacher.visible = true;
```
But the teacher model's name label? makePerson with name '' or no name. In intro, the teacher uses female, glasses, tie. Use same opts.

Add a subtle "teacher writing on board" pose? animatePerson idle is fine; maybe gesture 0.2. We can animate with `gesture: 0.25` to raise her right arm toward the board. Since she's facing north (yaw π) with the board behind her (south), gesture makes no sense. She faces north toward the class, gesturing while talking. Fine, `talk: 0` no gesture. Could add slow head movement; idle sway is enough.

Update loop: In updateGame, bots update only in else. Add `for (const b of this.bots) b.update(dt);` in skip branch, and animate teacher:
```
if (this.classTeacher?.visible && this.phase==='skip') animatePerson(this.classTeacher, dt, {mode:'idle', speed:0});
```
Need to update teacher only when phase skip; when hidden no.

In beginLockdown: hide classTeacher, set classroom=false, hide bots. In beginPlay, ensure classTeacher hidden.

hideGameplayEntities: hide/show classTeacher based on v and phase? During cutscenes, hide. Add `if (this.classTeacher) this.classTeacher.visible = !v && this.phase === 'skip';` but hideGameplayEntities(false) is called at end of intro before beginSkip (phase title), so it'd hide. Then beginSkip shows. During lockdown play, v=true hides. Fine.
But hideGameplayEntities(false) inside cinematic.finish during lockdown? beginPlay sets phase 'play'. No teacher. Fine.

Also hideGameplayEntities iterates bots and sets visible = !v && !escaped, which would show classroom bots during a cutscene end; immediately overwritten. Fine.

Bots' `classroom` mode and `dormant`: in beginSkip set dormant=false, classroom=true. Name sprites hidden in update (next frame); there may be a one-frame show, fine. Set immediately too.

In beginSkip `this.jake.spawn(-8.6, 2.35, 0)` — yaw 0 faces +z (south) toward the player/door. Good.

But Jake's goal is (-4,-8.4) in the toilets. He'll start moving immediately even if the player hasn't left. His path from (-8.6,2.35) through the toilet door at x -3..-1 z -3; findPath uses navNodes nearest; will route along corridor. Fine. He'll walk north/east. To wait for the player at the door, we can set a condition in JakeNPC.update: if the player is still in Room 101 (z > 3) and this.game.phase === 'skip', speed=0 and face the player. But then he stands in the corridor just outside, waiting. Once the player steps out (z<3), he moves. This makes the opening clean: Jake waiting, then leads. Let's implement:
```
const playerInClass = player.pos.z > 3.05;
if (this.game.phase === 'skip' && playerInClass) { speed=0; face player; say ...? } else { ... }
```
Currently speed = pd<8.5 ? ...; add condition. And set `lookAt: player.pos` when speed 0 already. Good. Also maybe say "Come on." when player exits. Not necessary.

Let's edit JakeNPC update.

