const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const sleep = ms => new Promise(r=>setTimeout(r,ms));
(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader','--ignore-gpu-blocklist'] });
  const context = await browser.newContext({ viewport: { width: 844, height: 390 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
  const page = await context.newPage();
  page.setDefaultTimeout(120000);
  const errs=[]; page.on('pageerror', e=>{errs.push(e.message); console.log('ERR',e.message);});
  await page.goto('http://localhost:8123/', { waitUntil: 'load' });
  await page.waitForTimeout(2600);
  await page.tap('#btn-play');
  await page.waitForFunction(() => window.__game.cinematic.active === true, null, { timeout: 30000 });
  await page.evaluate(() => window.__game.cinematic.finish());
  await page.waitForFunction(() => window.__game.phase === 'skip' && window.__game.state === 'play', null, { timeout: 30000 });
  await page.waitForTimeout(800);
  const ui = await page.evaluate(() => {
    const el = document.getElementById('touch-ui');
    return { visible: !el.classList.contains('hidden'), touch: window.__game.touch,
      display: getComputedStyle(el).display };
  });
  console.log('TOUCH', JSON.stringify(ui));
  await page.screenshot({ path:'/tmp/opencode/mobile-skip.jpg', type:'jpeg', quality: 84 });
  await page.tap('#tb-crouch');
  await page.tap('#tb-flash');
  await page.waitForTimeout(400);
  const toggles = await page.evaluate(() => ({
    crouchHeld: window.__game.crouchHeld,
    crouch: window.__game.player.crouch,
    torch: window.__game.player.torchOn,
    speed: window.__game.player.speed
  }));
  console.log('TOGGLES', JSON.stringify(toggles));
  const run = await page.$('#tb-sprint');
  const box = await run.boundingBox();
  await page.touchscreen.tap(box.x + box.width/2, box.y + box.height/2);
  // press-and-hold via pointer events
  await page.dispatchEvent('#tb-sprint', 'pointerdown', { pointerId: 7 });
  await page.waitForTimeout(250);
  const held = await page.evaluate(() => window.__game.sprintHeld);
  await page.dispatchEvent('#tb-sprint', 'pointerup', { pointerId: 7 });
  await page.waitForTimeout(150);
  const released = await page.evaluate(() => window.__game.sprintHeld);
  console.log('SPRINT', held, released);
  await page.screenshot({ path:'/tmp/opencode/mobile-crouch.jpg', type:'jpeg', quality: 84 });
  console.log('ERRS', errs.length, errs.slice(0,5));
  await browser.close();
})();
EOF
