    speed: this.speed,
    talk: this.talkTimer > 0 ? 1 : 0,
    lookAt: seen ? target.pos : null,
    gesture: this.detect > 0.3 ? 0.5 : 0.12
  });

  if (this.laserT > 0) this.updateLaser(dt);

