const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  page.setDefaultTimeout(30000);
  const errs = [];
  page.on('pageerror', e => errs.push(e.message));
  const waitCine = name => page.waitForFunction(n => window.__game.cinematic.active && window.__game.cinematic.name === n, name);
  const finishCine = name => page.evaluate(n => { const c = window.__game.cinematic; if (!c.active || c.name !== n) throw new Error(`Expected active ${n}, got ${c.name}/${c.active}`); c.finish(); }, name);
  const start = async () => {
    await page.goto('http://localhost:3000/', { waitUntil: 'load' });
    await page.waitForTimeout(600);
    await page.click('#btn-play');
    await waitCine('intro');
    await finishCine('intro');
    await page.waitForFunction(() => window.__game.phase === 'skip' && window.__game.state === 'play');
  };

  await start();
  await page.evaluate(() => { const g = window.__game, p = g.principal, e = g.player; p.spawn(e.pos.x, e.pos.z, e.yaw); p.detect = 1; g.onDetected(p); });
  await page.waitForFunction(() => window.__game.state === 'caught');
  const detected = await page.evaluate(() => ({ state: __game.state, phase: __game.phase, title: document.querySelector('#caught-title')?.textContent?.trim(), kicker: document.querySelector('#caught-kicker')?.textContent?.trim(), visible: !document.querySelector('#caught-screen')?.classList.contains('hidden') }));

  await start();
  await page.evaluate(() => window.__game.beginLockdown());
  await waitCine('lockdown');
  const lockdownStarted = await page.evaluate(() => ({ phase: __game.phase, state: __game.state, cinematic: __game.cinematic.name, active: __game.cinematic.active }));
  await finishCine('lockdown');
  await page.waitForFunction(() => window.__game.phase === 'play' && window.__game.state === 'play');
  const chapter = await page.evaluate(() => { const g = __game, k = g.killer; return { phase: g.phase, state: g.state, spawn: g.player.pos.toArray(), killer: { active: k.active, pos: k.pos.toArray(), state: k.state }, sprint: 5.75, chaseSpeed: 4.6, speedRatio: 5.75 / 4.6 }; });

  const behavior = await page.evaluate(() => {
    const g = __game, k = g.killer;
    k.active = true; k.pos.set(g.player.pos.x + 3, 0, g.player.pos.z); k.state = 'chase'; k.target = g.player;
    g.player.downed = true; k.update(0.016);
    const stoppedChasingDowned = k.state !== 'chase' || k.target !== g.player;
    k.state = 'investigate'; k.searchTimer = 0; k.update(0.016);
    const disengaged = k.state !== 'investigate' || !k.target || !k.target.downed;
    g.player.downed = false; k.pos.set(-20, 0, 0); k.state = 'patrol'; k.patrolTimer = 0; k.update(0.016);
    return { stoppedChasingDowned, disengaged, state: k.state, targetDowned: !!k.target?.downed, pathLength: k.path.length, speedRatio: 5.75 / 4.6 };
  });

  await page.evaluate(() => { const g = window.__game; g.player.escaped = true; g.finishRun(); });
  await waitCine('forgot');
  const forgot = await page.evaluate(() => ({ state: __game.state, phase: __game.phase, cinematic: __game.cinematic.name, active: __game.cinematic.active }));
  await finishCine('forgot'); await waitCine('jake');
  const reveal = await page.evaluate(() => ({ state: __game.state, cinematic: __game.cinematic.name, active: __game.cinematic.active }));
  await finishCine('jake'); await waitCine('police');
  const police = await page.evaluate(() => ({ state: __game.state, cinematic: __game.cinematic.name, active: __game.cinematic.active }));
  await finishCine('police');
