nearestDownedBot(max) {
  const e = this.getControl();
  let best = null, bd = max;
  for (const b of this.bots) {
    if (!b.downed || b.dead || b.escaped || b === e) continue;
    const d = Math.hypot(b.pos.x - e.pos.x, b.pos.z - e.pos.z);
    if (d < bd) { bd = d; best = b; }
  }
  return best;
},

