  if (!e || e.downed || e.escaped) { UI.prompt(null); return; }
  if (e.hidden) { UI.prompt('LEAVE HIDING', 0, 'E'); return; }
  const mate = this.nearestDownedBot(2.15);
  if (mate) {
    if (this.keysPressed['e']) {
