const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  page.setDefaultTimeout(40000);
  const errs = [];
  page.on('pageerror', e => errs.push(e.message));
  const waitCine = n => page.waitForFunction(x => window.__game.cinematic.active && window.__game.cinematic.name === x, n);
  const fin = n => page.evaluate(x => { const c = window.__game.cinematic; if (!c.active || c.name !== x) throw new Error('expected ' + x + ' got ' + c.name); c.finish(); }, n);

  await page.goto('http://localhost:3000/', { waitUntil: 'load' });
  await page.waitForTimeout(700);
  await page.click('#btn-play');
  await waitCine('intro'); await fin('intro');
  await page.waitForFunction(() => __game.phase === 'skip' && __game.state === 'play');

  // Chapter zero: walk the finish-line condition (both player and Jake inside toilets).
  const skipStage = await page.evaluate(() => {
    const g = __game;
    const start = { player: g.player.pos.toArray(), jake: g.jake.pos.toArray(), doorOpen: g.world.doors.find(d => d.room?.id === 'toilets')?.open };
    g.jake.pos.set(-5.2, 0, -4.2);
    g.player.pos.set(-3.4, 0, -4.6);
    return start;
  });
  await waitCine('lockdown');
  const lockdown = await page.evaluate(() => ({ phase: __game.phase, state: __game.state, name: __game.cinematic.name }));
  await fin('lockdown');
  await page.waitForFunction(() => __game.phase === 'play' && __game.state === 'play');

  // Chapter one: collect the real key chain through real door/item logic.
  const progression = await page.evaluate(() => {
    const g = __game, w = g.world;
    g.killer.active = false;
    g.killer.pos.set(60, 0, 40);
    const log = [];
    const grab = (item, note) => {
      if (!item) { log.push(note + ': MISSING'); return; }
      g.player.pos.set(item.x, 0, item.z + 0.6);
      g.collectItem(item, g.player);
      log.push(note + ': ' + (item.picked ? 'picked' : 'FAILED'));
    };
    const key1 = w.keyItems.find(k => k.data.keyId === 1);
    grab(key1, 'key1');
    for (let label = 1; label <= 7; label++) {
      const door = w.doorByLabel[label];
      if (!door) { log.push('door' + label + ': MISSING'); continue; }
      door.unlock();
      door.setOpen(true, false);
      const key = w.keyItems.find(k => k.data.keyId === label + 1);
      grab(key, 'key' + (label + 1));
    }
    grab(w.crowbarItem, 'crowbar');
    return { log, keys: [...g.player.keys].sort((a, b) => a - b), crowbar: g.player.crowbar, keyCount: w.keyItems.length, exitUnlocked: w.exit.unlocked, barricaded: w.exit.barricaded };
  });

  // Real exit interaction: unlock, pry, then step through.
  const exitStage = await page.evaluate(() => {
    const g = __game;
    g.player.pos.set(57.6, 0, 0);
    const before = { unlocked: g.world.exit.unlocked, barricaded: g.world.exit.barricaded };
    g.handleExit(g.player);
    const afterUnlock = { unlocked: g.world.exit.unlocked, barricaded: g.world.exit.barricaded };
    g.handleExit(g.player);
    const afterPry = { unlocked: g.world.exit.unlocked, barricaded: g.world.exit.barricaded, open: g.world.exit.open };
    g.handleExit(g.player);
    return { before, afterUnlock, afterPry, state: g.state, escaped: g.player.escaped, pending: g.pendingSwitch };
  });
  await page.waitForFunction(() => __game.controlledBot != null || __game.state === 'cutscene', null, { timeout: 15000 });

  const survivors = [];
  for (let i = 0; i < 4; i++) {
    const info = await page.evaluate(() => {
      const g = __game;
      if (g.state === 'cutscene' || g.controlledBot == null) return null;
      const e = g.getControl();
      e.pos.set(57.6, 0, 0);
      g.handleExit(e);
      return { name: e.name || 'PLAYER', escaped: e.escaped, state: g.state };
    });
    if (info) survivors.push(info);
    const done = await page.evaluate(() => __game.state === 'cutscene' && __game.cinematic.active);
    if (done) break;
    await page.waitForTimeout(1600);
  }
  await waitCine('forgot');
  const forgot = await page.evaluate(() => ({ state: __game.state, name: __game.cinematic.name, escaped: __game.bots.filter(b => b.escaped).length + (__game.player.escaped ? 1 : 0) }));
  await fin('forgot'); await waitCine('jake');
  await fin('jake'); await waitCine('police');
  await fin('police');
  await page.waitForFunction(() => __game.state === 'win');
  const ending = await page.evaluate(() => ({ state: __game.state, keys: __game.player.keys.size, crowbar: __game.player.crowbar, grade: document.querySelector('#win-grade')?.textContent?.trim(), survivors: __game.bots.filter(b => b.escaped).length + (__game.player.escaped ? 1 : 0) }));
  await page.screenshot({ path: '/tmp/opencode/playthrough.jpg', type: 'jpeg', quality: 78 });
  console.log(JSON.stringify({ skipStage, lockdown, progression, exitStage, survivors, forgot, ending, errs }, null, 2));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

