const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  page.setDefaultTimeout(120000);
  const errs = [];
  page.on('pageerror', e => errs.push(e.message));
  const waitCine = n => page.waitForFunction(x => window.__game.cinematic.active && window.__game.cinematic.name === x, n, { timeout: 120000 });
  const shot = async (name, ms = 900) => { await page.waitForTimeout(ms); await page.screenshot({ path: `/tmp/opencode/tour-${name}.jpg`, type: 'jpeg', quality: 82 }); };

  await page.goto('http://localhost:3000/', { waitUntil: 'load' });
  await page.waitForTimeout(800);
  await page.click('#btn-play');
  await waitCine('intro');
  await shot('01-intro', 1200);
  await page.evaluate(() => __game.cinematic.finish());
  await page.waitForFunction(() => __game.phase === 'skip' && __game.state === 'play');
  await shot('02-skip-classroom', 1400);

  // Walk through the door out to Jake using real input-ish movement.
  await page.evaluate(() => {
    const g = __game;
    g.player.pos.set(-7.4, 0, 1.4);
    g.player.yaw = Math.PI; g.camYaw = Math.PI;
    g.jake.pos.set(-7.8, 0, -2.2);
  });
  await shot('03-hall-jake', 1200);

  await page.evaluate(() => {
    const g = __game;
    g.jake.pos.set(-5.2, 0, -4.2);
    g.player.pos.set(-3.4, 0, -4.6);
  });
  await waitCine('lockdown');
  await shot('04-lockdown-a', 1400);
  await shot('05-lockdown-b', 1600);
  await page.evaluate(() => __game.cinematic.finish());
  await page.waitForFunction(() => __game.phase === 'play' && __game.state === 'play');
  await shot('06-chapter-one-spawn', 1200);

  // End sequence: skip straight to the post-escape beats.
  await page.evaluate(() => { const g = __game; g.player.escaped = true; for (const b of g.bots) b.escaped = true; g.finishRun(); });
  await waitCine('forgot');
  await shot('07-forgot-jake', 1500);
  await shot('08-forgot-jake-b', 1600);
  await page.evaluate(() => __game.cinematic.finish());
  await waitCine('jake');
  await shot('09-reveal', 1400);
  await shot('10-reveal-b', 1600);
  await page.evaluate(() => __game.cinematic.finish());
  await waitCine('police');
  await shot('11-police', 1400);
  await shot('12-police-b', 1600);
  await page.evaluate(() => __game.cinematic.finish());
  await page.waitForFunction(() => __game.state === 'win');
  await shot('13-win', 800);

  console.log(JSON.stringify({ errs, files: 13 }));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

