const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
async function run(width, height, tag) {
  const browser = await chromium.launch({ headless: true, args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist'] });
  const page = await browser.newPage({ viewport: { width, height }, hasTouch: true, deviceScaleFactor: 2 });
  page.setDefaultTimeout(120000);
  await page.goto('http://localhost:3000/', { waitUntil: 'load' });
  await page.waitForTimeout(500);
  await page.evaluate(() => {
    const g = __game;
    g.showWin();
  });
  await page.waitForTimeout(1200);
  const info = await page.evaluate(() => {
    const inner = document.querySelector('.win-inner');
    const r = inner.getBoundingClientRect();
    const s = document.getElementById('win-stats').getBoundingClientRect();
    const b = document.getElementById('btn-again').getBoundingClientRect();
    return { vw: innerWidth, vh: innerHeight, inner: [r.x, r.y, r.width, r.height].map(Math.round), stats: [s.x, s.y, s.width, s.height].map(Math.round), button: [b.x, b.y, b.width, b.height].map(Math.round), fits: r.top >= 0 && r.bottom <= innerHeight, scrollH: document.body.scrollHeight };
  });
  console.log(tag, JSON.stringify(info));
  await page.screenshot({ path: `/tmp/opencode/win-${tag}.png` });
  await browser.close();
}
(async () => {
  await run(844, 390, 'mobile-landscape');
  await run(390, 844, 'mobile-portrait');
  await run(1280, 720, 'desktop');
})();

