const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist'] });
  const context = await browser.newContext({ viewport: { width: 844, height: 390 }, hasTouch: true });
  const page = await context.newPage();
  page.setDefaultTimeout(120000);
  const errs = []; page.on('pageerror', e => { errs.push(e.message); console.log('ERR', e.message); });
  await page.goto('http://localhost:3000/', { waitUntil: 'load' });
  await page.waitForTimeout(1500);
  const titleTouch = await page.evaluate(() => !document.getElementById('touch-ui').classList.contains('hidden'));
  await page.tap('#btn-play');
  await page.waitForFunction(() => window.__game.cinematic.active === true, null, { timeout: 30000 });
  await page.evaluate(() => window.__game.cinematic.finish());
  await page.waitForFunction(() => window.__game.phase === 'skip' && window.__game.state === 'play', null, { timeout: 30000 });
  await page.waitForTimeout(800);
  const playTouch = await page.evaluate(() => !document.getElementById('touch-ui').classList.contains('hidden'));
  const hit = await page.evaluate(() => ['tb-crouch', 'tb-flash', 'tb-sprint', 'tb-interact'].map(id => {
    const el = document.getElementById(id); const r = el.getBoundingClientRect();
    const top = document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2);
    return { id, top: top?.id || top?.tagName };
  }));
  for (const id of ['tb-crouch', 'tb-flash']) {
    await page.dispatchEvent('#' + id, 'pointerdown', { pointerId: 31, pointerType: 'touch', isPrimary: true });
    await page.dispatchEvent('#' + id, 'pointerup', { pointerId: 31, pointerType: 'touch', isPrimary: true });
  }
  await page.waitForTimeout(350);
  const toggles = await page.evaluate(() => ({ crouchHeld: __game.crouchHeld, crouch: __game.player.crouch, torch: __game.player.torchOn, torchHud: document.getElementById('torch-state').textContent }));
  await page.dispatchEvent('#tb-sprint', 'pointerdown', { pointerId: 32, pointerType: 'touch', isPrimary: true });
  await page.waitForTimeout(200);
  const held = await page.evaluate(() => __game.sprintHeld);
  await page.dispatchEvent('#tb-sprint', 'pointerup', { pointerId: 32, pointerType: 'touch', isPrimary: true });
  await page.waitForTimeout(150);
  const released = await page.evaluate(() => __game.sprintHeld);
  // Pause hides the touch layer, resume restores it.
  await page.evaluate(() => __game.togglePause(true));
  await page.waitForTimeout(150);
  const pausedTouch = await page.evaluate(() => !document.getElementById('touch-ui').classList.contains('hidden'));
  await page.evaluate(() => __game.togglePause(false));
  await page.waitForTimeout(150);
  const resumedTouch = await page.evaluate(() => !document.getElementById('touch-ui').classList.contains('hidden'));
  await page.screenshot({ path: '/tmp/opencode/mobile-play.png' });
  console.log(JSON.stringify({ titleTouch, playTouch, hit, toggles, sprint: [held, released], pausedTouch, resumedTouch, errs }, null, 2));
  await browser.close();
})();

