const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const URL = 'http://localhost:3000/';
async function launch(viewport, touch) {
  const browser = await chromium.launch({ headless: true, args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist'] });
  const page = await browser.newPage({ viewport, hasTouch: touch, deviceScaleFactor: 2 });
  page.setDefaultTimeout(120000);
  const errs = []; page.on('pageerror', e => errs.push(e.message));
  await page.goto(URL, { waitUntil: 'load' });
  await page.waitForTimeout(1400);
  return { browser, page, errs };
}
const rect = sel => `(() => { const el = document.querySelector(${JSON.stringify(sel)}); if (!el) return null; const r = el.getBoundingClientRect(); return { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height), bottom: Math.round(r.bottom), right: Math.round(r.right), vw: innerWidth, vh: innerHeight, fits: r.top >= 0 && r.left >= 0 && r.bottom <= innerHeight + 1 && r.right <= innerWidth + 1 }; })()`;

(async () => {
  for (const [tag, vp] of [['landscape', { width: 844, height: 390 }], ['portrait', { width: 390, height: 844 }], ['tablet', { width: 1024, height: 768 }]]) {
    const { browser, page, errs } = await launch(vp, true);
    const out = { tag };
    out.title = await page.evaluate(rect('.title-inner'));
    await page.screenshot({ path: `/tmp/opencode/audit-${tag}-title.png` });

    // Controls screen
    await page.tap('#btn-controls');
    await page.waitForTimeout(400);
    out.controls = await page.evaluate(rect('#controls-screen .panel'));
    await page.screenshot({ path: `/tmp/opencode/audit-${tag}-controls.png` });
    await page.evaluate(() => document.getElementById('controls-screen').classList.add('hidden'));

    // Gameplay
    await page.tap('#btn-play');
    await page.waitForFunction(() => __game.cinematic.active);
    await page.evaluate(() => __game.cinematic.finish());
    await page.waitForFunction(() => __game.phase === 'skip' && __game.state === 'play');
    await page.waitForTimeout(900);
    out.play = await page.evaluate(() => {
      const ids = ['objective-panel', 'map-panel', 'status-panel', 'stick-zone', 'touch-buttons'];
      const box = id => { const el = document.getElementById(id); const r = el.getBoundingClientRect(); return { id, x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height), right: Math.round(r.right), bottom: Math.round(r.bottom) }; };
      const b = ids.map(box);
      const overlap = (a, c) => a.x < c.x + c.w && a.x + a.w > c.x && a.y < c.y + c.h && a.y + a.h > c.y;
      return { boxes: b, objectiveStatusOverlap: overlap(b[0], b[2]), statusStickOverlap: overlap(b[2], b[3]), vw: innerWidth, vh: innerHeight };
    });
    await page.screenshot({ path: `/tmp/opencode/audit-${tag}-play.png` });

    // Pause
    await page.evaluate(() => __game.togglePause(true));
    await page.waitForTimeout(300);
    out.pause = await page.evaluate(rect('#pause-screen .panel'));
    await page.screenshot({ path: `/tmp/opencode/audit-${tag}-pause.png` });
    await page.evaluate(() => __game.togglePause(false));

    // Note popup
    await page.evaluate(() => { const g = __game; const it = g.world.notes[0]; if (it) g.collectItem(it, g.player); });
    await page.waitForTimeout(400);
    out.note = await page.evaluate(rect('#note-popup .note'));
    await page.screenshot({ path: `/tmp/opencode/audit-${tag}-note.png` });

    out.errs = errs;
    console.log(JSON.stringify(out));
    await browser.close();
  }
})();
